from lib import *
S = SS('f86')
R = J('f86'); cp = R['cmp']; ne = R['nest']; m2 = R['m2o']; ch = R['chunk']
jl, sl, nl = cp['joinedload'], cp['selectinload'], cp['不预加载(lazy,N+1)']
steps = [
    step("两者发出的 SQL:joinedload 加 limit(5) 时,SQLAlchemy 把作者部分包进带 LIMIT 的子查询(SELECT ... FROM (SELECT author... LIMIT 5) AS anon_1),再 LEFT OUTER JOIN book——这样 LIMIT 限制的是作者数而不是连接后的行数;selectinload 发 2 条:第一条查作者(LIMIT 5),第二条是 SELECT book.author_id, book.id, book.title FROM book WHERE book.author_id IN (5 个主键占位符)。", t=tl(S(1)), done=lidx(S(1), 'joinedload', 'selectinload'), kv=KV([['joinedload', 'LEFT OUTER JOIN,limit 时包子查询'], ['selectinload', '第二条 WHERE ... IN (主键列表)']], ['selectinload'])),
    step("joinedload 一对多时结果里同一个作者会重复出现,所以必须调用 .unique():不调用,执行 scalars().all() 抛 InvalidRequestError「The unique() method must be invoked on this Result, as it contains results that include joined eager loads against collections」。", t=tl(S(2)), mark=lidx(S(2), 'InvalidRequestError'), kv=KV([['joinedload + 集合', '结果必须 .unique()']], ['joinedload + 集合'])),
    step(f"取 300 个作者(每人一个 4000 字节的 bio 列)和各自的 10 本书,PostgreSQL 本机、7 次取中位数:不预加载(N+1){nl[0]:.1f} ms、{nl[1]} 条 SQL;joinedload {jl[0]:.1f} ms、{jl[1]} 条;selectinload {sl[0]:.1f} ms、{sl[1]} 条。JOIN 的结果集有 {R['join_rows']} 行,作者的 bio 在每一行里都重复一遍;selectin 的两条查询分别返回 300 行与 3000 行。三种方式取到的作者与书的数量相同(300 与 3000)。", b=bars([['不预加载', nl[0], f'{nl[0]:.1f} ms'], ['joinedload', jl[0], f'{jl[0]:.1f} ms'], ['selectinload', sl[0], f'{sl[0]:.1f} ms']], nl[0], mark=[0], done=[1, 2]), t=tl(S(3)), done=lidx(S(3), 'joinedload', 'selectinload'), mark=lidx(S(3), '不预加载'), kv=KV([['N+1', f'{nl[1]} 条'], ['joinedload', f'{jl[0]:.1f} ms,1 条,行数 3000'], ['selectinload', f'{sl[0]:.1f} ms,2 条']], ['selectinload'])),
    step(f"多层嵌套 Author → books → reviews(300 × 10 × 3):joinedload 链 {ne['joinedload 链'][0]:.1f} ms、1 条 SQL,结果集是作者 × 书 × 评论的乘积(9000 行);selectinload 链 {ne['selectinload 链'][0]:.1f} ms、{ne['selectinload 链'][1]} 条 SQL(1 条作者、1 条书,3000 本书的评论被 IN 列表分成 6 块)。", b=bars([['joinedload 链', ne['joinedload 链'][0], f"{ne['joinedload 链'][0]:.1f} ms"], ['selectinload 链', ne['selectinload 链'][0], f"{ne['selectinload 链'][0]:.1f} ms"]], ne['joinedload 链'][0], mark=[0], done=[1]), t=tl(S(4)), done=lidx(S(4), 'selectinload 链'), mark=lidx(S(4), 'joinedload 链'), kv=KV([['joinedload 链', '1 条,行数相乘'], ['selectinload 链', f"{ne['selectinload 链'][1]} 条,每条行数小"]], ['joinedload 链'])),
    step(f"多对一:joinedload(Book.author) 每本书只连一个作者,行数不增加,{m2['joinedload(Book.author)'][0]:.1f} ms、1 条 SQL;selectinload(Book.author) {m2['selectinload(Book.author)'][0]:.1f} ms、{m2['selectinload(Book.author)'][1]} 条(取 1500 本书)。本机上两者差别不大。", t=tl(S(5)), done=lidx(S(5), 'joinedload', 'selectinload'), kv=KV([['多对一', 'joinedload 不放大行数']], ['多对一'])),
    step(f"selectinload 的 IN 列表按块发送,每块最多 500 个主键:300 个作者 {ch['300']} 条 SQL(1 + 1)、600 个 {ch['600']} 条(1 + 2)、1200 个 {ch['1200']} 条(1 + 3)。", t=tl(S(6)), done=lidx(S(6), '个作者'), kv=KV([['300', f"{ch['300']} 条"], ['600', f"{ch['600']} 条"], ['1200', f"{ch['1200']} 条"]], ['1200'])),
]
A = mkartf('f86', 86, 'Flask,SQLAlchemy,joinedload,selectinload,N+1,真实验证,动画演示',
    f'在真实的 PostgreSQL 上对比 joinedload 与 selectinload:发出的 SQL(limit 时包子查询、IN 列表)、一对多必须 unique()、300 个作者 3000 本书的耗时({nl[0]:.1f} / {jl[0]:.1f} / {sl[0]:.1f} ms)、多层嵌套时 JOIN 行数相乘、多对一的差别、IN 列表每块 500 个主键。',
    '什么时候用 joinedload,什么时候用 selectinload?一对多为什么必须 unique()?嵌套多层时哪个更划算?这篇在真实的 PostgreSQL 上把两者的 SQL、行数、耗时和分块行为逐项量出来。',
    [(f'{jl[0]:.1f} vs {sl[0]:.1f} ms', '300 个作者 + 3000 本书:joinedload 与 selectinload 的耗时(PG 本机,中位数)'), ('9000 行', '三层嵌套用 joinedload 时 JOIN 返回的行数(300 × 10 × 3)'), ('500', 'selectinload 每块 IN 列表最多的主键数')],
    [('发出的 SQL', '<p>上一篇:<a href="flask-lazy-eager-loading.html">Lazy Loading 与 Eager Loading</a>;下一篇:<a href="flask-n-plus-one.html">N+1 查询问题</a>。</p>'), ('必须 unique()', None), ('一对多的耗时', '<p>数据库在本机、关了 fsync,所以只看相对关系,不看绝对值。</p>'), ('多层嵌套', None), ('多对一', None), ('IN 列表分块', None)],
    steps, [ENV_F + '。Flask-SQLAlchemy 3.1.1、psycopg 3.3.6、自己起的 PostgreSQL(非默认端口,本机回环)', '没有验证:数据库与应用跨网络时往返次数对耗时的影响(本机几乎没有网络延迟,会低估 N+1 与多条 SQL 的代价)、contains_eager、subqueryload 的耗时、大 bio 列以外的行宽、MySQL 与 SQLite 上的对比'], 'joinedload 与 selectinload', panels=[('t', 'term', '实验输出'), ('b', 'bars', '耗时'), ('kv', 'kv', '要点')])
